from pathlib import Path
import re

path=Path('index.html')
s=path.read_text(encoding='utf-8')
orig=s

def replace_once(old,new,label):
    global s
    count=s.count(old)
    if count!=1:
        raise SystemExit(f'{label}: expected 1 match, found {count}')
    s=s.replace(old,new,1)

marker='@media(min-width:700px){.two-col{grid-template-columns:1fr 1fr}}'
css='''\n.study-setup{background:#fff;border:1px solid var(--border);border-radius:24px;padding:18px;margin-top:14px;box-shadow:0 8px 28px rgba(16,24,40,.05)}.study-setup-head{margin-bottom:14px}.study-setup-head h2{margin:0 0 5px;font-size:22px}.study-setup-head p{margin:0;color:var(--muted);font-size:14px;line-height:1.55}.study-mode-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.study-mode{appearance:none;text-align:left;border:2px solid #e2e8f0;border-radius:18px;padding:14px;min-height:116px;background:#fff;color:var(--text);cursor:pointer;transition:.15s ease}.study-mode:hover{border-color:#bfd0ff;background:#fbfcff}.study-mode.selected{border-color:var(--accent);background:var(--soft);box-shadow:0 0 0 2px rgba(47,111,237,.08)}.study-mode-icon{display:block;font-size:24px;margin-bottom:7px}.study-mode strong{display:block;font-size:16px;margin-bottom:4px}.study-mode span:last-child{display:block;color:var(--muted);font-size:12px;line-height:1.45;font-weight:600}.study-detail{margin-top:14px;border:1px solid #e2e8f0;border-radius:16px;background:#fafbfc;overflow:hidden}.study-detail summary{cursor:pointer;list-style:none;padding:13px 14px;font-weight:800;color:#344054}.study-detail summary::-webkit-details-marker{display:none}.study-detail summary:after{content:'＋';float:right;color:#667085}.study-detail[open] summary:after{content:'−'}.study-detail-body{border-top:1px solid #e2e8f0;padding:14px;display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.setting-field label{display:block;font-size:12px;font-weight:800;color:#667085;margin:0 0 6px}.setting-field select{min-height:48px;font-size:15px}.setting-field.full{grid-column:1/-1}.setup-actions{display:grid;grid-template-columns:1fr auto auto;gap:10px;margin-top:14px}.setup-actions .primary{min-height:56px;font-size:17px}.setup-actions .secondary,.setup-actions .danger{width:auto;min-width:140px}.setup-message{min-height:20px;margin-top:10px;font-size:13px;color:var(--bad);font-weight:700}.quiz-session{display:block}.session-hidden{display:none!important}.dash-back{width:auto;min-width:0;margin-bottom:12px}.style-hint{margin-top:8px;padding:10px 12px;border-radius:12px;background:#f8fafc;color:#475467;font-size:13px;line-height:1.5}.mock-note{color:#1d4ed8;font-weight:700}\n@media(max-width:700px){.study-mode-grid{grid-template-columns:1fr}.study-mode{min-height:88px;padding:12px 14px}.study-mode-icon{display:inline-block;margin:0 8px 0 0;vertical-align:middle}.study-mode strong{display:inline}.study-mode span:last-child{margin-top:5px}.study-detail-body{grid-template-columns:1fr}.setting-field.full{grid-column:auto}.setup-actions{grid-template-columns:1fr 1fr}.setup-actions .primary{grid-column:1/-1}.setup-actions .secondary,.setup-actions .danger{min-width:0;width:100%}}\n'''
if '.study-setup{' not in s:
    replace_once(marker,css+marker,'css marker')

old_controls='''<div class="controls">\n<button class="secondary wide" id="backToCatalog">← 教材を選び直す</button>\n<div><label>出題範囲</label><select id="mode"><option value="all">全問</option></select></div>\n<label class="toggle"><input type="checkbox" id="shuffle">問題順をシャッフル</label>\n<button class="primary wide" id="restart">開始／やり直し</button>\n<button class="secondary" id="dashBtn">学習状況を見る</button>\n<button class="danger" id="resetBtn">この教材の履歴をリセット</button>\n</div>'''
new_controls='''<button class="secondary" id="backToCatalog">← マイ教材へ戻る</button>\n<div class="study-setup" id="studySetup">\n<div class="study-setup-head"><h2>学び方を選ぶ</h2><p>普段は「続きから」がおすすめです。必要なときだけ復習や模試へ切り替えられます。</p></div>\n<div class="study-mode-grid" id="studyModeGrid">\n<button class="study-mode selected" type="button" data-study-style="continue"><span class="study-mode-icon">▶</span><strong>続きから</strong><span>前回位置があればそこから。なければ選択範囲の先頭から学習します。</span></button>\n<button class="study-mode" type="button" data-study-style="review"><span class="study-mode-icon">↻</span><strong>苦手復習</strong><span>間違えた問題や未クリア問題を中心に繰り返します。</span></button>\n<button class="study-mode" type="button" data-study-style="mock"><span class="study-mode-icon">⌁</span><strong>全問模試</strong><span>選択範囲の全問題をランダム順で出題します。</span></button>\n</div>\n<div class="style-hint" id="styleHint">前回の学習位置を優先して再開します。</div>\n<details class="study-detail" id="studyDetail"><summary>詳細設定</summary><div class="study-detail-body">\n<div class="setting-field"><label for="mode">出題範囲</label><select id="mode"><option value="all">全範囲</option></select></div>\n<div class="setting-field"><label for="questionLimit">出題数</label><select id="questionLimit"><option value="all">すべて</option><option value="10">10問</option><option value="20">20問</option></select></div>\n<div class="setting-field full" id="reviewTargetField"><label for="reviewTarget">苦手復習の対象</label><select id="reviewTarget"><option value="combined">間違えた問題 ＋ 未クリア問題</option><option value="wrong">間違えた問題だけ</option><option value="uncleared">未クリア問題だけ</option></select></div>\n<label class="toggle setting-field full" id="shuffleField"><input type="checkbox" id="shuffle">問題順をシャッフル</label>\n</div></details>\n<div class="setup-message" id="setupMessage"></div>\n<div class="setup-actions"><button class="primary" id="restart">この設定で学習する</button><button class="secondary" id="dashBtn">学習状況</button><button class="danger" id="resetBtn">履歴リセット</button></div>\n</div>'''
if 'id="studySetup"' not in s:
    replace_once(old_controls,new_controls,'controls block')

old_dash='<section class="card" id="dash" style="display:none"><div class="qhead">学習状況</div><div class="small" id="dashHelp" style="margin-bottom:12px"></div><div class="dashboard" id="dashGrid"></div></section>'
new_dash='<section class="card" id="dash" style="display:none"><button class="secondary dash-back" id="dashBackBtn">← 出題設定に戻る</button><div class="qhead">学習状況</div><div class="small" id="dashHelp" style="margin-bottom:12px"></div><div class="dashboard" id="dashGrid"></div></section>'
if 'id="dashBackBtn"' not in s:
    replace_once(old_dash,new_dash,'dash block')

old_const="const $=id=>document.getElementById(id),mode=$('mode'),shuffle=$('shuffle'),options=$('options');"
new_const="const $=id=>document.getElementById(id),mode=$('mode'),shuffle=$('shuffle'),options=$('options'),questionLimit=$('questionLimit'),reviewTarget=$('reviewTarget');\nlet studyStyle='continue';"
if "let studyStyle='continue';" not in s:
    replace_once(old_const,new_const,'const refs')

pattern=r"async function loadCourse\(item,resumeQuestionNumber=null\)\{.*?\nfunction render\(\)\{"
m=re.search(pattern,s,re.S)
if not m:
    raise SystemExit('load/config/start block not found')
new_block='''async function loadCourse(item,resumeQuestionNumber=null){\ntry{const courseUrl=new URL(item.file,location.href).href;const r=await fetch(courseUrl,{cache:'no-store'});if(!r.ok)throw new Error(`教材ファイル取得失敗 HTTP ${r.status} (${item.file})`);let data;try{data=await r.json()}catch{throw new Error(`教材JSONの解析に失敗しました (${item.file})`)}validateCourse(data,item.id);const cc=Number(data.clear_count);COURSE={course_id:data.course_id,title:data.title||item.title||'学習問題アプリ',subtitle:data.subtitle||'',section_label:data.section_label||'区分',clear_count:Number.isInteger(cc)&&cc>0?cc:3,questions:data.questions};QUESTIONS=COURSE.questions;configureCourse();$('catalogView').classList.add('hidden');$('courseView').classList.remove('hidden');if(resumeQuestionNumber!==null){studyStyle='continue';syncStudyStyleUI();beginStudy(resumeQuestionNumber)}else{showStudySetup()}}catch(e){alert('教材を読み込めませんでした。\\n'+String(e))}\n}\nfunction configureCourse(){document.title=COURSE.title||'スタディカード';$('courseTitle').textContent=COURSE.title||'学習問題アプリ';$('courseSubtitle').textContent=COURSE.subtitle||'';KEY=storageKey();migrateLegacy();mode.innerHTML='<option value="all">全範囲</option>';for(const d of sections()){const o=document.createElement('option');o.value='section:'+d;o.textContent=`${COURSE.section_label} ${d}`;mode.append(o)}mode.value='all';questionLimit.value='all';reviewTarget.value='combined';shuffle.checked=false;studyStyle='continue';$('notice').textContent=`現在${QUESTIONS.length}問収録です。各問題は${COURSE.clear_count}回正解するとクリアになります。`;$('dashHelp').textContent=`${COURSE.clear_count}回正解でクリア。履歴はこの端末のブラウザ内に教材別で保存されます。`;syncStudyStyleUI()}\nfunction setStudyStyle(style){studyStyle=style;syncStudyStyleUI()}\nfunction syncStudyStyleUI(){document.querySelectorAll('[data-study-style]').forEach(b=>b.classList.toggle('selected',b.dataset.studyStyle===studyStyle));const review=studyStyle==='review',mock=studyStyle==='mock';$('reviewTargetField').classList.toggle('hidden',!review);shuffle.disabled=mock;if(mock)shuffle.checked=true;else if(shuffle.dataset.forcedMock==='1'){shuffle.checked=false}shuffle.dataset.forcedMock=mock?'1':'0';$('styleHint').innerHTML=studyStyle==='continue'?'前回の学習位置を優先して再開します。':review?'間違えた問題・未クリア問題を既存履歴から抽出します。詳細設定で対象を絞れます。':'<span class="mock-note">模試では問題順を自動でランダム化します。</span>';$('setupMessage').textContent=''}\nfunction showStudySetup(message=''){$('studySetup').classList.remove('hidden');$('notice').style.display='none';$('courseView').querySelector('.status').style.display='none';$('quizCard').style.display='none';$('feedback').style.display='none';$('actions').style.display='none';$('dash').style.display='none';$('setupMessage').textContent=message;syncStudyStyleUI()}\nfunction rangedQuestions(){const v=mode.value;if(v==='all')return [...QUESTIONS];if(v.startsWith('section:'))return QUESTIONS.filter(q=>String(q.day)===v.slice(8));return [...QUESTIONS]}\nfunction beginStudy(resumeQuestionNumber=null){let pool=rangedQuestions();if(studyStyle==='review'){const t=reviewTarget.value;if(t==='wrong')pool=pool.filter(q=>stat(q.number).wrong>0);else if(t==='uncleared')pool=pool.filter(q=>!cleared(q));else pool=pool.filter(q=>stat(q.number).wrong>0||!cleared(q))}const mustShuffle=studyStyle==='mock'||shuffle.checked;if(mustShuffle)pool=mix(pool);const lim=questionLimit.value==='all'?null:Number(questionLimit.value);if(lim&&lim>0)pool=pool.slice(0,lim);active=pool;current=correct=answered=0;locked=false;if(!active.length){showStudySetup(studyStyle==='review'?'条件に合う復習問題はありません。対象条件を変更してください。':'対象となる問題はありません。');return}let target=resumeQuestionNumber;if(target===null&&studyStyle==='continue'){const last=loadLastStudy();if(last&&String(last.course_id)===String(COURSE.course_id))target=last.question_number}if(target!==null){const idx=active.findIndex(q=>String(q.number)===String(target));if(idx>=0)current=idx}$('studySetup').classList.add('hidden');$('notice').style.display='block';$('courseView').querySelector('.status').style.display='block';$('dash').style.display='none';$('quizCard').style.display='block';$('actions').style.display='grid';$('feedback').style.display='none';render()}\nfunction render(){'''
s=s[:m.start()]+new_block+s[m.end():]

old_show="function showDash(){$('dash').style.display='block';$('quizCard').style.display='none';$('feedback').style.display='none';$('actions').style.display='none';"
new_show="function showDash(){$('studySetup').classList.add('hidden');$('notice').style.display='none';$('courseView').querySelector('.status').style.display='none';$('dash').style.display='block';$('quizCard').style.display='none';$('feedback').style.display='none';$('actions').style.display='none';"
if old_show in s:
    s=s.replace(old_show,new_show,1)
elif new_show not in s:
    raise SystemExit('showDash prefix not found')

old_handlers="$('restart').onclick=start;$('answerBtn').onclick=()=>{};$('nextBtn').onclick=next;$('dashBtn').onclick=showDash;$('resetBtn').onclick=()=>{if(confirm('この教材の学習履歴をすべて削除しますか？')){localStorage.removeItem(KEY);alert('学習履歴を削除しました。');start()}};"
new_handlers="document.querySelectorAll('[data-study-style]').forEach(b=>b.onclick=()=>setStudyStyle(b.dataset.studyStyle));$('restart').onclick=()=>beginStudy();$('answerBtn').onclick=()=>{};$('nextBtn').onclick=next;$('dashBtn').onclick=showDash;$('dashBackBtn').onclick=()=>showStudySetup();$('resetBtn').onclick=()=>{if(confirm('この教材の学習履歴をすべて削除しますか？')){localStorage.removeItem(KEY);alert('学習履歴を削除しました。');showStudySetup()}};"
if old_handlers in s:
    s=s.replace(old_handlers,new_handlers,1)
elif "$('restart').onclick=()=>beginStudy();" not in s:
    raise SystemExit('handlers block not found')

if 'function start(){' in s or "$('restart').onclick=start" in s:
    raise SystemExit('old start still present')
if s==orig:
    raise SystemExit('no changes made')
path.write_text(s,encoding='utf-8')
print('Phase UI-3 patch applied:', len(orig), '->', len(s))
